namespace AmznSellingPartner.Clients.Orders.OrdersV0
{
    using Newtonsoft.Json;

    /// <summary>
    /// Contains information regarding the Shipping Settings Automation program, such as whether the
    /// order's shipping settings were generated automatically, and what those settings are.
    /// </summary>
    public class AutomatedShippingSettings : BaseClass
    {
        /// <summary>
        /// When true, this order has automated shipping settings generated by Amazon. This order could
        /// be identified as an SSA order.
        /// </summary>
        [JsonProperty("HasAutomatedShippingSettings")]
        public bool HasAutomatedShippingSettings { get; set; }

        /// <summary>
        /// Auto-generated carrier for SSA orders.
        /// </summary>
        [JsonProperty("AutomatedCarrier")]
        public string AutomatedCarrier { get; set; }

        /// <summary>
        /// Auto-generated ship method for SSA orders.
        /// </summary>
        [JsonProperty("AutomatedShipMethod")]
        public string AutomatedShipMethod { get; set; }
    }
}
